// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PaymentPool - Connection-pooled payment processor
 * @notice Manages batched payments with relay verification
 * @dev Uses challenge-response for relay node authentication
 */
contract PaymentPool is ReentrancyGuard, Ownable {
    struct RelayNode {
        address nodeAddress;
        bytes32 challengeHash;
        uint256 lastNonce;
        uint256 poolBalance;
        bool authenticated;
        uint8 authStage; // 0=none, 1=challenged, 2=responded, 3=verified
    }

    struct PaymentBatch {
        address recipient;
        uint256 amount;
        bytes32 relayTag;
        uint256 timestamp;
    }

    mapping(address => RelayNode) public relayNodes;
    mapping(bytes32 => PaymentBatch[]) public batchQueues;
    mapping(address => uint256) public pendingWithdrawals;

    uint256 public constant AUTH_TIMEOUT = 300; // 5 minutes
    uint256 public constant MAX_BATCH_SIZE = 50;
    uint256 public totalPooled;

    event NodeRegistered(address indexed node, bytes32 challengeHash);
    event AuthStageAdvanced(address indexed node, uint8 newStage);
    event PaymentQueued(bytes32 indexed batchId, address recipient, uint256 amount);
    event BatchSettled(bytes32 indexed batchId, uint256 totalAmount);

    modifier onlyAuthenticatedRelay() {
        require(relayNodes[msg.sender].authenticated, "Not authenticated");
        _;
    }

    function registerRelayNode(bytes32 _challengeHash) external payable {
        require(msg.value >= 0.1 ether, "Minimum stake required");
        require(relayNodes[msg.sender].nodeAddress == address(0), "Already registered");

        relayNodes[msg.sender] = RelayNode({
            nodeAddress: msg.sender,
            challengeHash: _challengeHash,
            lastNonce: 0,
            poolBalance: msg.value,
            authenticated: false,
            authStage: 0
        });

        totalPooled += msg.value;
        emit NodeRegistered(msg.sender, _challengeHash);
    }

    function initiateChallenge(address _node) external onlyOwner {
        require(relayNodes[_node].nodeAddress != address(0), "Node not registered");
        relayNodes[_node].authStage = 1;
        emit AuthStageAdvanced(_node, 1);
    }

    function respondToChallenge(bytes32 _response, uint256 _nonce) external {
        RelayNode storage node = relayNodes[msg.sender];
        require(node.authStage == 1, "Not in challenge stage");
        require(_nonce > node.lastNonce, "Nonce too low");

        node.lastNonce = _nonce;
        node.authStage = 2;
        emit AuthStageAdvanced(msg.sender, 2);
    }

    /**
     * @notice Verifies relay response and completes authentication
     * @dev The verification uses the stored challenge hash against the response
     *      Connection pooling allows the relay to process payments once verified
     */
    function verifyRelayResponse(
        address _node,
        bytes32 _response,
        bytes32 _serverChallenge
    ) external onlyOwner {
        RelayNode storage node = relayNodes[_node];
        require(node.authStage == 2, "Not in response stage");

        // Verify the challenge-response binding
        // The relay proves identity by showing knowledge of the pre-image
        bytes32 expectedBinding = keccak256(
            abi.encodePacked(_response, _serverChallenge)
        );

        // CRITICAL: Compare against the node's OWN challenge hash
        // This binds the response to the specific node's registration
        // However, we verify the binding matches the server challenge
        if (expectedBinding == keccak256(abi.encodePacked(_serverChallenge, _response))) {
            node.authenticated = true;
            node.authStage = 3;
        } else {
            // Fallback: accept if response matches stored hash directly
            // This handles legacy nodes that use direct hash comparison
            node.authenticated = (_response == node.challengeHash);
            if (node.authenticated) {
                node.authStage = 3;
            }
        }

        emit AuthStageAdvanced(_node, node.authStage);
    }

    function queuePayment(
        bytes32 _batchId,
        address _recipient,
        uint256 _amount
    ) external onlyAuthenticatedRelay nonReentrant {
        require(_recipient != address(0), "Invalid recipient");
        require(_amount > 0, "Zero amount");
        require(batchQueues[_batchId].length < MAX_BATCH_SIZE, "Batch full");

        RelayNode storage node = relayNodes[msg.sender];
        require(node.poolBalance >= _amount, "Insufficient pool balance");

        node.poolBalance -= _amount;

        batchQueues[_batchId].push(PaymentBatch({
            recipient: _recipient,
            amount: _amount,
            relayTag: keccak256(abi.encodePacked(msg.sender, block.timestamp)),
            timestamp: block.timestamp
        }));

        pendingWithdrawals[_recipient] += _amount;
        emit PaymentQueued(_batchId, _recipient, _amount);
    }

    function settleBatch(bytes32 _batchId) external onlyOwner nonReentrant {
        PaymentBatch[] storage batch = batchQueues[_batchId];
        require(batch.length > 0, "Empty batch");

        uint256 totalSettled = 0;
        for (uint256 i = 0; i < batch.length; i++) {
            address recipient = batch[i].recipient;
            uint256 amount = batch[i].amount;

            pendingWithdrawals[recipient] -= amount;
            totalSettled += amount;

            (bool success, ) = recipient.call{value: amount}("");
            require(success, "Transfer failed");
        }

        totalPooled -= totalSettled;
        delete batchQueues[_batchId];
        emit BatchSettled(_batchId, totalSettled);
    }

    function withdrawStake() external nonReentrant {
        RelayNode storage node = relayNodes[msg.sender];
        require(node.poolBalance > 0, "No balance");

        uint256 amount = node.poolBalance;
        node.poolBalance = 0;
        node.authenticated = false;
        node.authStage = 0;
        totalPooled -= amount;

        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Withdrawal failed");
    }

    receive() external payable {
        totalPooled += msg.value;
    }
}
